param([Parameter(Mandatory)][string]$RequestPath,[Parameter(Mandatory)][string]$RequestSha256)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Hash-File([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Read-Object([string]$p){$raw=[IO.File]::ReadAllText($p);$v=if((Get-Command ConvertFrom-Json).Parameters.ContainsKey('DateKind')){$raw|ConvertFrom-Json -DateKind String}else{$raw|ConvertFrom-Json};if($v -isnot [pscustomobject]){throw 'Witness object required'};return $v}
function Bind-Process([object]$row){if($null -eq $row -or -not $row.ExecutablePath -or -not $row.CommandLine){throw 'Witness bound actor unreadable'};$h=[Security.Cryptography.SHA256]::Create();try{$cmd=([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($row.CommandLine)))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};return @{pid=[int]$row.ProcessId;creationDate=$row.CreationDate.ToUniversalTime().ToString('o');executableSha256=(Hash-File $row.ExecutablePath);commandLineSha256=$cmd}}
if(-not [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Independent witness requires actual elevated read access'}
$intentFile=Join-Path $PSScriptRoot 'RECOVERY-INTENT.json';$intent=Read-Object $intentFile;$manifestFile=Join-Path $PSScriptRoot 'MANIFEST.json';if((Hash-File $manifestFile) -cne $intent.codeManifestSha256){throw 'Witness manifest changed'};$manifest=Read-Object $manifestFile
if((Hash-File $PSCommandPath) -cne $manifest.code.'witness.ps1'){throw 'Witness bytes changed'}
if([IO.Path]::GetFullPath((Split-Path -Parent $RequestPath)) -ine [IO.Path]::GetFullPath($intent.outputDirectory) -or [IO.Path]::GetFileName($RequestPath) -cnotmatch '^WITNESS-REQUEST-([a-f0-9]{32})\.json$'){throw 'Witness request escaped exact attempt'}
$requestId=$Matches[1];if((Hash-File $RequestPath) -cne $RequestSha256){throw 'Witness request SHA changed'};$request=Read-Object $RequestPath
if($request.version -cne '6dc-census-request-v1' -or $request.requestId -cne $requestId -or $request.intentSha256 -cne (Hash-File $intentFile) -or $request.originalFailureSha256 -cne $intent.originalFailureSha256 -or $request.observerBridgeSha256 -cne $manifest.code.'observe.ps1' -or $request.witnessScriptSha256 -cne $manifest.code.'witness.ps1'){throw 'Witness request binding differs'}
$date=[DateTimeOffset]::Parse($request.at);if($date -gt [DateTimeOffset]::UtcNow -or ([DateTimeOffset]::UtcNow-$date).TotalSeconds -ge 120){throw 'Witness request stale'}
$rows=@(Get-CimInstance Win32_Process -ErrorAction Stop)
foreach($name in @('owner','observer')){$found=@($rows|Where-Object ProcessId -eq $request.$name.pid);if($found.Count -ne 1){throw 'Requested observer or owner not live'};$actual=Bind-Process $found[0];foreach($key in @('pid','creationDate','executableSha256','commandLineSha256')){if($actual.$key -cne $request.$name.$key){throw 'Requested observer or owner exact binding changed'}}}
$records=@($rows|Where-Object {$_.Name -imatch '^(powershell|pwsh|python|pythonw|waitress-serve|node|workerd|wsl)(\.exe)?$'}|ForEach-Object {if(-not $_.ExecutablePath -or -not $_.CommandLine){throw 'Even elevated witness cannot classify relevant process'};[ordered]@{pid=[int]$_.ProcessId;parentPid=[int]$_.ParentProcessId;name=[string]$_.Name;creationDate=$_.CreationDate.ToUniversalTime().ToString('o');exe=[string]$_.ExecutablePath;command=[string]$_.CommandLine}})
if((Hash-File $RequestPath) -cne $RequestSha256){throw 'Witness request changed during census'}
$result=[ordered]@{version='6dc-census-witness-v1';at=[DateTimeOffset]::UtcNow.ToString('o');requestId=$requestId;requestSha256=$RequestSha256;intentSha256=$request.intentSha256;originalFailureSha256=$request.originalFailureSha256;observer=$request.observer;owner=$request.owner;elevated=$true;producer=(Bind-Process @($rows|Where-Object ProcessId -eq $PID)[0]);records=$records}
$destination=Join-Path $intent.outputDirectory ('WITNESS-'+$requestId+'.json');$temporary=$destination+'.'+[guid]::NewGuid().ToString('N')+'.tmp';$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($result|ConvertTo-Json -Depth 12 -Compress)+"`n");$stream=[IO.File]::Open($temporary,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($temporary,$destination)
@{path=$destination;sha256=(Hash-File $destination);processCount=$records.Count;productionLifecycleActions=$false}|ConvertTo-Json -Compress
